function T(chars, size, style, color, opts) {
  const t = figma.createText();
  t.fontName = {family:"Montserrat", style:style||"Regular"};
  t.characters = chars;
  t.fontSize = size;
  t.fills = [{type:"SOLID", color: color || C.ink}];
  if (opts) {
    if (opts.strike) t.textDecoration = "STRIKETHROUGH";
    if (opts.align) t.textAlignHorizontal = opts.align;
    if (opts.lh) t.lineHeight = {value: opts.lh, unit:"PIXELS"};
  }
  return t;
}
